mapper.select:
SELECT COUNT(0)
FROM `fave`.`board_posts`
WHERE `deleted_at` IS NULL;

SELECT `index` AS `index`, `title` AS `title`, `content` AS `content`, `user_email` AS `userEmail`, `user_nickname` AS `userNickname`, `create_at` AS `createdAt`, `update_at` AS `updatedAt`, `deleted_at` AS `deletedAt`, `view` AS `view`, `like_count` AS `likesCount`, (SELECT COUNT(*) FROM `fave`.`board_comments` WHERE `post_id` = `fave`.`board_posts`.`index` AND `is_deleted` IS FALSE) AS `commentCount` FROM `fave`.`board_posts` WHERE `deleted_at` IS NULL
AND (`title` LIKE CONCAT('%', #{keyword}, '%'))
AND `title` LIKE CONCAT('%', #{keyword}, '%')
AND `user_nickname` = #{keyword}
ORDER BY `index` DESC LIMIT #{offsetCount}, #{limitCount}
